import{_ as t,o as s,c as r,ah as n}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Registre et emploi du temps","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/enseignant/registre-et-emploi-du-temps.md","filePath":"src/guide/enseignant/registre-et-emploi-du-temps.md"}'),a={name:"guide/enseignant/registre-et-emploi-du-temps.md"};function i(o,e,l,d,u,p){return s(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="registre-et-emploi-du-temps" tabindex="-1">Registre et emploi du temps <a class="header-anchor" href="#registre-et-emploi-du-temps" aria-label="Permalink to &quot;Registre et emploi du temps&quot;">​</a></h1><p>Cette page couvre deux consultations indépendantes : le registre de votre classe si vous êtes professeur principal, et votre propre emploi du temps, accessible à tout enseignant.</p><h2 id="le-registre-de-classe-professeur-principal" tabindex="-1">Le registre de classe (professeur principal) <a class="header-anchor" href="#le-registre-de-classe-professeur-principal" aria-label="Permalink to &quot;Le registre de classe (professeur principal)&quot;">​</a></h2><p>Si vous êtes désigné professeur principal d&#39;une ou plusieurs classes, le menu <strong>Enseignement → Ma classe</strong> vous donne une vue consolidée de chacune d&#39;elles.</p><p>Pour chaque classe, un tableau récapitule, par élève :</p><table tabindex="0"><thead><tr><th>Colonne</th><th>Contenu</th></tr></thead><tbody><tr><td>Élève</td><td>Nom de l&#39;élève</td></tr><tr><td>Moyenne annuelle</td><td>Moyenne de l&#39;élève sur l&#39;année, toutes matières</td></tr><tr><td>Absences non justifiées</td><td>Nombre d&#39;absences sans justificatif approuvé</td></tr><tr><td>Incidents disciplinaires</td><td>Nombre d&#39;incidents enregistrés pour cet élève</td></tr></tbody></table><p>Ce tableau est une vue de suivi en lecture seule. À côté du nom de chaque classe, le bouton <strong>Appréciations de fin de période</strong> vous amène à la saisie décrite dans <a href="/era-guide/guide/enseignant/bulletins-et-cahier-texte.html">Bulletins et cahier de textes</a>.</p><p>Si vous n&#39;êtes actuellement professeur principal d&#39;aucune classe, la page l&#39;indique et ne propose rien d&#39;autre.</p><h2 id="consulter-votre-emploi-du-temps" tabindex="-1">Consulter votre emploi du temps <a class="header-anchor" href="#consulter-votre-emploi-du-temps" aria-label="Permalink to &quot;Consulter votre emploi du temps&quot;">​</a></h2><p>Le menu <strong>Enseignement → Mon emploi du temps</strong> affiche vos créneaux de cours de la semaine : jour, heure de début, heure de fin, classe et matière. Le bouton <strong>Exporter (iCal)</strong> télécharge votre emploi du temps dans un fichier que vous pouvez importer dans votre application de calendrier personnelle (Google Agenda, Outlook, Apple Calendrier…).</p>',10)])])}const g=t(a,[["render",i]]);export{m as __pageData,g as default};
